DO $$
DECLARE
  v_quiz_id_10 uuid;
BEGIN
  INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
  VALUES ('أحكام الخمس وموارد وجوبه الشائعة', 'إسلاميات', 'فقه جعفري عملي', 'standard', 'ar', true)
  RETURNING id INTO v_quiz_id_10;

  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_10, 'ما هي نسبة الخمس الواجب إخراجه من أرباح المكاسب بعد استثناء مؤونة السنة؟', '["الخُمس أي خمس المال","الربع","الثلث","العشر"]'::jsonb, 0, 20, 0, 'multi', 'يجب إخراج خُمس ما زاد من أرباح المكاسب عن مؤونة السنة وهو الخمس أي 20 بالمئة وفق ما نصّ عليه الفقه الجعفري استناداً إلى آية الغنيمة.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_10, 'استناداً إلى الفقه الجعفري كيف يُقسَّم الخمس على المستحقين؟', '["يُوزَّع على ستة أسهم متساوية","يُدفع كله للمرجع الديني","نصفان متساويان بين الفقراء والأيتام فقط","نصف لسهم الإمام ونصف يُقسم على السادة الفقراء والأيتام وأبناء السبيل"]'::jsonb, 3, 20, 1, 'multi', 'يُقسَّم الخمس نصفين: سهم الإمام ويكون في زمن الغيبة لمرجع التقليد، وسهم السادة يُوزَّع على بني هاشم من فقراء وأيتام وأبناء سبيل وفق الفقه الإمامي.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_10, 'أيّ من الموارد التالية يُعدّ من موارد وجوب الخمس في الفقه الجعفري؟', '["الهدايا والهبات مطلقاً","المال الذي يختلط الحلال فيه بالحرام ولا يُعرف صاحبه","الإرث المعتاد من الأقارب","الزكاة المدفوعة للفقراء"]'::jsonb, 1, 20, 2, 'multi', 'من موارد الخمس المال المختلط بالحرام إذا جهل مقداره وصاحبه فيجب إخراج خمسه تطهيراً له وفق الفقه الجعفري.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_10, 'ما المقصود بـ''مؤونة السنة'' التي تُستثنى من أرباح المكاسب قبل احتساب الخمس؟', '["ثمن البيت والسيارة فقط","ما يُدفع ضريبةً للدولة","المصاريف الضرورية وما يليق بشأن المكلف وعياله خلال السنة","ما يُنفق على الأعمال الخيرية فقط"]'::jsonb, 2, 20, 3, 'multi', 'المؤونة هي النفقات المعتادة التي يحتاجها المكلف وعياله خلال السنة مما يليق بشأنه عرفاً من مأكل وملبس ومسكن وتعليم وغيرها.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_10, 'ما حكم الأرض التي يشتريها ذمّيٌّ من مسلم في الفقه الجعفري؟', '["لا خمس فيها مطلقاً","يُكتفى بدفع الزكاة عنها","تُصادَر لبيت المال","يجب على الذمّي إخراج خمسها"]'::jsonb, 3, 20, 4, 'multi', 'ذهب مشهور فقهاء الإمامية إلى أن الأرض التي يشتريها الذمّي من المسلم يجب فيها الخمس ويكون على الذمّي إخراجه.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_10, 'ما هو حكم المعادن التي يستخرجها الإنسان في الفقه الجعفري من حيث الخمس؟', '["يجب فيها الخمس كاملاً دون خصم أي تكاليف","يجب فيها الخمس بعد إخراج مؤونة الاستخراج إذا بلغت النصاب","يجب فيها ربع العشر فقط","لا خمس فيها وإنما تجب الزكاة"]'::jsonb, 1, 20, 5, 'multi', 'المعادن من موارد الخمس الستة، ويجب إخراج خمسها بعد استثناء مؤونة الاستخراج إذا بلغت النصاب المحدد شرعاً.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_10, 'ما السنة الخمسية في اصطلاح الفقه الجعفري؟', '["تحديد سنة مالية للمكلف يُحاسَب فيها على أرباحه ويُخرج خمس ما زاد عن مؤونتها","مدة خمس سنوات لتسديد الخمس بالتقسيط","الفترة الخمسية التي يُراجَع فيها المرجع الديني","الفترة التي تسقط بعدها المطالبة بالخمس"]'::jsonb, 0, 20, 6, 'multi', 'السنة الخمسية هي السنة المالية التي يعيّنها المكلف لنفسه أو يعيّنها له المرجع، وفي نهايتها يحاسب نفسه على أرباحه ويُخرج خمس ما زاد عن مؤونته.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_10, 'ما حكم الكنز الذي يعثر عليه شخص في الفقه الجعفري؟', '["تجب فيه الزكاة لا الخمس","يُسلَّم بالكامل لبيت المال","يعود بالكامل لصاحبه الواجد ولا خمس فيه","يجب إخراج خمسه بعد استثناء مؤونة استخراجه إذا بلغ النصاب"]'::jsonb, 3, 20, 7, 'multi', 'الكنز من موارد وجوب الخمس الستة، ويُخرج خمسه إذا بلغ نصابه المحدد بعشرين ديناراً ذهباً أو مائتي درهم فضة وفق المشهور.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_10, 'ما موقف الفقه الجعفري من الإرث الذي لم يكن متوقعاً ولم يُحتسب في الميزانية الاعتيادية للمكلف؟', '["لا خمس فيه مطلقاً لأن الإرث لا خمس فيه بالإجماع","يُعامَل معاملة الزكاة لا الخمس","يرى بعض المراجع وجوب الخمس في الإرث غير المتوقع الذي لم يُعهد عادةً","يجب فيه نصف الخمس فقط"]'::jsonb, 2, 20, 8, 'multi', 'الإرث المتعارف لا خمس فيه عند المشهور، غير أن بعض المراجع المعاصرين يرون وجوب الخمس في الإرث الكثير غير المعتاد الذي يعدّه العرف ربحاً طارئاً.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_10, 'ما حكم من تأخّر في أداء الخمس عن موعده المحدد دون عذر شرعي؟', '["يُضاعَف عليه المبلغ بمرور الوقت","يبقى الخمس ديناً في ذمته ويأثم بالتأخير وعليه الأداء مهما طال الزمن","يسقط عنه الخمس ولا شيء عليه","يكفي الاستغفار عن التأخير"]'::jsonb, 1, 20, 9, 'multi', 'الخمس حق شرعي ثابت في الذمة لا يسقط بالتأخير، ويأثم المكلف على التسويف، ويبقى ملزماً بأدائه في أي وقت وفق نصوص الفقه الإمامي.', 'فقه جعفري عملي');
END $$;



DO $$
DECLARE
  v_quiz_id_11 uuid;
BEGIN
  INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
  VALUES ('أحكام الزكاة والمعاملات المالية المعاصرة', 'إسلاميات', 'فقه جعفري عملي', 'standard', 'ar', true)
  RETURNING id INTO v_quiz_id_11;

  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_11, 'ما هو النصاب الأول للذهب الذي تجب فيه الزكاة وفق الفقه الجعفري؟', '["خمسة عشر مثقالاً","خمسة عشر ديناراً","عشرة مثاقيل","عشرون مثقالاً"]'::jsonb, 3, 20, 0, 'multi', 'النصاب الأول للذهب عشرون مثقالاً صيرفياً، وفيه نصف مثقال زكاةً، وهذا ما أجمع عليه فقهاء الإمامية استناداً إلى روايات أهل البيت عليهم السلام.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_11, 'هل تجب الزكاة في الأوراق النقدية المعاصرة وفق رأي أغلب مراجع الشيعة الإمامية؟', '["تجب وجوباً قطعياً كالذهب والفضة","تجب إذا بلغت نصاب الفضة فقط","لا تجب لأنها ليست من الأصناف التسعة","تجب احتياطاً استحبابياً فقط"]'::jsonb, 2, 20, 1, 'multi', 'أغلب مراجع الإمامية يرون أن الزكاة الواجبة محددة بتسعة أصناف، والأوراق النقدية ليست منها، غير أنهم يستحبون إخراجها تورعاً، ومنهم السيد السيستاني والسيد الخامنئي.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_11, 'ما الشرط الزمني اللازم لوجوب زكاة الذهب والفضة في الفقه الجعفري؟', '["مرور حول كامل وهو اثنا عشر شهراً قمرياً","مرور ستة أشهر هجرية","لا يشترط مرور حول","مرور سنة ميلادية كاملة"]'::jsonb, 0, 20, 2, 'multi', 'يشترط الفقه الجعفري مرور الحول أي اثني عشر شهراً قمرياً على بلوغ النصاب بقاءً واستمراراً، فإن نقص النصاب في أثناء الحول انقطع الحول وبدأ من جديد.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_11, 'ما حكم أرباح التجارة والأعمال الحرة في الفقه الجعفري؟', '["تجب فيها الزكاة والخمس معاً","يجب فيها الخمس لا الزكاة","لا يجب فيها شيء","تجب فيها الزكاة بعد الحول"]'::jsonb, 1, 20, 3, 'multi', 'أرباح التجارة والأعمال تخضع للخمس لا للزكاة في الفقه الجعفري، إذ الخمس يجب في كل فائدة ومكسب بعد استثناء مؤونة السنة، استناداً لقوله تعالى ''واعلموا أنما غنمتم من شيء فإن لله خمسه''.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_11, 'ما حكم الاستثمار في الأسهم من حيث الخمس وفق الفقه الجعفري المعاصر؟', '["لا خمس فيها لأنها ورقية","يجب خمس الربح فقط عند البيع الفعلي","يجب خمس الربح المتحقق عند نهاية السنة الخمسية","يجب خمس رأس المال كله سنوياً"]'::jsonb, 2, 20, 4, 'multi', 'يرى أكثر المراجع وجوب تخميس الأرباح المتحققة سواء وزعت أم أضيفت للرأسمال عند حلول السنة الخمسية، فإن لم تتحقق الأرباح إلا عند البيع وجب الخمس حينئذٍ.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_11, 'ما المقصود بـ''مؤونة السنة'' التي تستثنى قبل إخراج الخمس في الفقه الجعفري؟', '["جميع ما يحتاجه المكلف وعياله في معيشتهم بالمعروف خلال السنة","نفقة الزوجة فقط","ديون الشخص المتراكمة","ربع الدخل السنوي تقديراً"]'::jsonb, 0, 20, 5, 'multi', 'مؤونة السنة هي مجموع ما أنفقه المكلف على نفسه وعياله من مسكن وملبس ومأكل وعلاج ودراسة وما شابه ذلك مما يليق بشأنه عرفاً، وما زاد بعدها يجب خمسه.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_11, 'ما حكم القرض بفائدة ''الربا'' الذي تمارسه البنوك التجارية في الفقه الجعفري؟', '["محرم مطلقاً في جميع الأحوال","جائز بعقد الحيلة الشرعية كالمرابحة والإجارة","جائز إذا كان بين مسلم وكافر","جائز إذا كانت الفائدة دون عشرة بالمئة"]'::jsonb, 1, 20, 6, 'multi', 'الربا محرم في الفقه الجعفري، غير أن المراجع أجازوا التعامل مع البنوك عبر صيغ شرعية كالمرابحة والمضاربة والإجارة والقرض الحسن، فيما يجيز بعضهم أخذ الفائدة من بنوك الدول غير الإسلامية بنية الاستنقاذ.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_11, 'ما الأصناف الثلاثة الأولى من مصارف الزكاة المذكورة في آية ''إنما الصدقات'' وفق ترتيب الآية الكريمة؟', '["الفقراء والغارمون وابن السبيل","المساكين والمؤلفة قلوبهم والغارمون","المساكين والرقاب وفي سبيل الله","الفقراء والمساكين وعاملون عليها"]'::jsonb, 3, 20, 7, 'multi', 'قال تعالى ''إنما الصدقات للفقراء والمساكين والعاملين عليها والمؤلفة قلوبهم وفي الرقاب والغارمين وفي سبيل الله وابن السبيل''، فالأول الفقراء ثم المساكين ثم العاملون عليها.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_11, 'ما حكم دفع الزكاة إلى الفقيه الجامع للشرائط أو وكيله في زماننا وفق كثير من مراجع الإمامية؟', '["واجب مطلقاً ولا يجوز الدفع لغيره","محرم لأن الزكاة اختصت بالإمام المعصوم فقط","جائز بل مستحب لأنه أعلم بمواردها وقد يكون واجباً في بعض الصور","مستحب لا واجب بأي حال"]'::jsonb, 2, 20, 8, 'multi', 'يرى كثير من المراجع الإمامية أن دفع الزكاة إلى الفقيه الجامع للشرائط أو وكيله مستحب لأنه أعرف بمواضعها، وقد يكون واجباً في حال توقف إقامة الشعائر الاجتماعية على ذلك، وللمكلف في غير ذلك أن يوزعها بنفسه.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_11, 'ما حكم شراء العملات الرقمية المشفرة كالبيتكوين من حيث الخمس وفق الاجتهادات المعاصرة للمراجع الجعفرية؟', '["هي محرمة فلا يترتب عليها حكم شرعي","يجب خمس الربح المتحقق منها ضمن السنة الخمسية كسائر الفوائد","لا خمس فيها لعدم ورودها في النصوص الشرعية","يجب خمس رأس المال فيها خاصةً لكونها مجهولة المالية"]'::jsonb, 1, 20, 9, 'multi', 'أفتى عدد من المراجع المعاصرين كالسيد السيستاني وغيره بأن الربح المتحقق من تداول العملات الرقمية يخضع لأحكام الخمس كسائر الأرباح والفوائد، فيجب إخراج خمس ما زاد عن مؤونة السنة.', 'فقه جعفري عملي');
END $$;



DO $$
DECLARE
  v_quiz_id_12 uuid;
BEGIN
  INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
  VALUES ('أحكام الطهارة الوضوء الغسل والتيمم', 'إسلاميات', 'فقه جعفري عملي', 'standard', 'ar', true)
  RETURNING id INTO v_quiz_id_12;

  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_12, 'ما هو الترتيب الصحيح لأعضاء الوضوء عند الإمامية الاثني عشرية؟', '["مسح الوجه ثم غسل اليدين ثم مسح الرأس ثم مسح الرجلين","غسل الوجه ثم اليدين من المرفق ثم مسح الرأس ثم مسح الرجلين","غسل الوجه ثم اليدين من الأصابع ثم مسح الرأس ثم الرجلين","غسل الوجه ثم اليدين من الكوع ثم مسح الرأس ثم غسل الرجلين"]'::jsonb, 1, 20, 0, 'multi', 'يجب في الوضوء الجعفري غسل الوجه واليدين من المرفق إلى الأصابع ومسح الرأس ومسح الرجلين من رؤوس الأصابع إلى الكعبين وفق ما دلت عليه الآية الكريمة وروايات أهل البيت عليهم السلام.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_12, 'ما حكم مسح الرجلين في الوضوء عند الفقه الجعفري؟', '["واجب غسلهما لا مسحهما","يتخير المكلف بين المسح والغسل","واجب من رؤوس الأصابع إلى الكعبين","مستحب ويجوز غسلهما بدلاً منه"]'::jsonb, 2, 20, 1, 'multi', 'يذهب الفقه الجعفري إلى وجوب مسح الرجلين لا غسلهما استناداً إلى قراءة الجر في الآية الكريمة وروايات الأئمة عليهم السلام ومنها ما رواه الكليني في الكافي.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_12, 'كم مقدار مسح الرأس الواجب في الوضوء الجعفري؟', '["مسح ربع الرأس فأكثر","مسح نصف الرأس الأمامي","مسح جميع الرأس من الجبهة إلى القفا","مسح بعضه بما يصدق عليه اسم المسح ولو بثلاث أصابع"]'::jsonb, 3, 20, 2, 'multi', 'يكفي في مسح الرأس أن يمسح بعضه بما يصدق عليه المسح عرفاً وهو المشهور عند الإمامية استناداً إلى دلالة الباء في قوله تعالى: ''وامسحوا برؤوسكم'' على التبعيض.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_12, 'ما هي نواقض الوضوء المتفق عليها في الفقه الجعفري؟', '["البول والغائط والريح والنوم والجنابة والحيض","البول والغائط والريح فقط","البول والغائط فقط","الجنابة والحيض والنوم فقط"]'::jsonb, 0, 20, 3, 'multi', 'تشمل نواقض الوضوء عند الإمامية: البول والغائط والريح الخارج من الموضع المعتاد والنوم الغالب على العقل والجنابة والحيض والاستحاضة والنفاس وفقاً لما ورد في المصادر الفقهية كالمبسوط للشيخ الطوسي وشرائع الإسلام للمحقق الحلي.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_12, 'ما هي الأغسال الواجبة في الفقه الجعفري؟', '["غسل الجنابة والحيض والنفاس فقط","غسل الجنابة والحيض والنفاس والاستحاضة ومس الميت وغسل الميت","غسل الجنابة والحيض فقط","غسل الجنابة فقط بوصفه أصل الأغسال"]'::jsonb, 1, 20, 4, 'multi', 'تشمل الأغسال الواجبة في الفقه الجعفري ستة: الجنابة والحيض والنفاس والاستحاضة ومس الميت وغسل الميت كما ذكرها المحقق الحلي في شرائع الإسلام والعلامة الحلي في تذكرة الفقهاء.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_12, 'ما الفرق بين الغسل الترتيبي والغسل الارتماسي في الفقه الجعفري؟', '["لا فرق بينهما في الصحة والأثر","الترتيبي يبدأ بالجانب الأيمن ثم الأيسر ثم الرأس والارتماسي للجنب فقط","الترتيبي للواجب والارتماسي للمستحب فقط","الترتيبي يبدأ بالرأس ثم الجانب الأيمن ثم الأيسر والارتماسي غمر الجسد كله دفعة واحدة"]'::jsonb, 3, 20, 5, 'multi', 'في الغسل الترتيبي يبدأ المكلف بغسل الرأس والرقبة ثم الجانب الأيمن ثم الأيسر أما الارتماسي فيرتمس البدن كله في الماء دفعة واحدة وكلاهما صحيح وفق المشهور في الفقه الجعفري كما في العروة الوثقى للسيد اليزدي.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_12, 'ما شروط التيمم في الفقه الجعفري؟', '["يجوز التيمم متى شاء المكلف بديلاً عن الوضوء","يجوز التيمم عند البرودة الشديدة فقط","تعذر استعمال الماء لعدمه أو الضرر أو الحرج أو ضيق الوقت","يشترط له الحصول على إذن من الفقيه"]'::jsonb, 2, 20, 6, 'multi', 'يجوز التيمم عند تعذر استعمال الماء لأسباب عدة منها: فقدان الماء أو الخوف من الضرر باستعماله أو الحرج الشديد أو ضيق الوقت وذلك استناداً إلى قوله تعالى: ''فلم تجدوا ماء فتيمموا'' وروايات أهل البيت عليهم السلام.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_12, 'على ماذا يصح التيمم في الفقه الجعفري؟', '["كل شيء طاهر حتى الخشب والقماش عند الضرورة","الأرض وما يصدق عليه اسم الأرض كالتراب والرمل والحجر","التراب فقط دون سائر أنواع الأرض","الجص والآجر فقط لأنهما من الأرض المحروقة"]'::jsonb, 1, 20, 7, 'multi', 'يصح التيمم على ما يصدق عليه اسم الأرض من تراب ورمل وحجر وطين وهو المشهور عند الإمامية استناداً إلى ما ورد في روايات الأئمة عليهم السلام ومنها قول الإمام الصادق: ''التراب أحد الطهورين''.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_12, 'ما كيفية التيمم الصحيح وفق الفقه الجعفري؟', '["ضربتان على الأرض الأولى للوجه والثانية لظاهر الكفين مع النية","ضربة واحدة يمسح بها الوجه واليدين معاً","ضربتان للوجه والرأس فقط دون اليدين","ثلاث ضربات للوجه واليدين والرجلين"]'::jsonb, 0, 20, 8, 'multi', 'كيفية التيمم عند الإمامية أن يضرب بيديه على الأرض ضربتين يمسح بالأولى جبهته وجبينيه ويمسح بالثانية ظاهر كفيه اليمنى بالكف اليسرى والعكس وذلك ما أفتى به الشيخ الطوسي والمحقق الحلي وجمهور الفقهاء.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_12, 'ما حكم الوضوء لمن أجنب في الفقه الجعفري؟', '["يجب الوضوء ثم الغسل معاً","يتخير بين الوضوء والغسل عند الجنابة","لا يصح الوضوء مع الجنابة ويجب الغسل بدلاً منه ويغني الغسل عن الوضوء","يصح الوضوء بدلاً عن الغسل عند العجز عنه"]'::jsonb, 2, 20, 9, 'multi', 'يذهب الفقه الجعفري إلى أن الجنابة ترفعها الغسل لا الوضوء وأن غسل الجنابة يغني عن الوضوء فلا يصح ضمهما معاً وذلك استناداً إلى روايات متعددة منها ما رواه الشيخ الطوسي في التهذيب عن الأئمة عليهم السلام.', 'فقه جعفري عملي');
END $$;



DO $$
DECLARE
  v_quiz_id_13 uuid;
BEGIN
  INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
  VALUES ('المعاملات والتجارة والصيد والأطعمة والأشربة', 'إسلاميات', 'فقه جعفري عملي', 'standard', 'ar', true)
  RETURNING id INTO v_quiz_id_13;

  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_13, 'ما هو شرط صحة البيع في الفقه الجعفري من حيث المتعاقدين؟', '["أن يكون البائع بالغاً عاقلاً مختاراً مالكاً أو مأذوناً","يكفي أن يكون البائع مسلماً فقط","يشترط أن يكون كلاهما من الذكور البالغين","يكفي الرضا الباطني دون إظهار"]'::jsonb, 0, 20, 0, 'multi', 'يشترط في المتعاقدين البلوغ والعقل والاختيار والملكية أو الإذن، وهذا مما اتفق عليه فقهاء الإمامية كالشيخ الطوسي في المبسوط والمحقق الحلي في شرائع الإسلام.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_13, 'ما حكم بيع الخمر في الفقه الجعفري؟', '["جائز إذا كان البائع غير مسلم","مكروه وليس محرماً","حرام وباطل مطلقاً","جائز للمضطر فقط"]'::jsonb, 2, 20, 1, 'multi', 'بيع الخمر باطل ومحرم بالإجماع في الفقه الجعفري، إذ لا يجوز بيع ما لا منفعة محللة فيه، كما نص على ذلك المحقق الحلي في شرائع الإسلام وصاحب الجواهر.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_13, 'ما المقصود بخيار المجلس في الفقه الجعفري؟', '["حق الفسخ يمتد ثلاثة أيام من وقت العقد","خيار يثبت للمشتري وحده دون البائع","هو خيار لا يثبت إلا في بيع الحيوان","حق كل من المتبايعين في فسخ البيع ما داما في المجلس قبل التفرق"]'::jsonb, 3, 20, 2, 'multi', 'خيار المجلس يثبت لكلا المتبايعين ما لم يتفرقا، مستنداً إلى الروايات عن أهل البيت عليهم السلام، وقد أقره المحقق الحلي والشيخ الأنصاري في المكاسب.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_13, 'ما حكم الصيد بالآلة دون ذكر اسم الله عليها في الفقه الجعفري؟', '["لا يحل أكل الصيد إذا لم يُذكر اسم الله عند إرسال الآلة","يحرم فقط إذا كان الصائد مسلماً","يحل الصيد حتى لو لم يُسمَّ لأن التسمية مستحبة فقط","يحل إذا ذكر اسم الله عند تناول الطعام"]'::jsonb, 0, 20, 3, 'multi', 'يشترط في الفقه الجعفري ذكر اسم الله عند إرسال الآلة أو الكلب المعلَّم، فإن تُرك عمداً لم يحل الصيد، وهذا مذهب المشهور كما في شرائع الإسلام وجواهر الكلام.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_13, 'ما حكم أكل السمك الذي مات حتف أنفه خارج الماء في الفقه الجعفري؟', '["يحرم إلا إذا كان من نوع السمك المقشور","يحل أكله لأن ذكاته إخراجه حياً من الماء","يحرم لأنه لم يذبح ذبحاً شرعياً","يحل فقط إذا مات في الشبكة"]'::jsonb, 1, 20, 4, 'multi', 'ذكاة السمك إخراجه من الماء حياً وإن مات بعد ذلك، فيحل أكله بشرط أن يكون له فلس. وهذا مذهب المشهور في الفقه الجعفري استناداً للروايات عن الأئمة عليهم السلام.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_13, 'ما الموقف الفقهي الجعفري من شرط الربا في عقد القرض؟', '["يجوز بالتراضي بين المسلمين","القرض والشرط كلاهما باطلان","يجوز اشتراط الزيادة إذا كانت يسيرة","الشرط باطل والقرض صحيح على المشهور"]'::jsonb, 3, 20, 5, 'multi', 'اشتراط الزيادة في القرض ربا محرم، والمشهور عند الإمامية أن الشرط يبطل دون أن يسري البطلان إلى أصل العقد، كما حققه الشيخ الأنصاري في المكاسب وصاحب الجواهر.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_13, 'ما حكم بيع الكلب في الفقه الجعفري؟', '["يجوز بيع جميع أنواع الكلاب","يحرم بيع كلب الصيد لأنه لا ثمن له","لا يجوز بيع الكلب غير المعلَّم للصيد، ويجوز بيع كلب الصيد المعلَّم","يجوز بيع الكلب الحارس للزرع فقط"]'::jsonb, 2, 20, 6, 'multi', 'المشهور في الفقه الجعفري أن الكلب غير المعلَّم لا يقع عليه البيع لعدم المنفعة المحللة، أما كلب الصيد المعلَّم فيجوز بيعه وله ثمن، كما في شرائع الإسلام وجواهر الكلام.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_13, 'ما شرط حِل الذبيحة في الفقه الجعفري من حيث الذابح؟', '["يشترط أن يكون الذابح مسلماً أو في حكمه، ولا تحل ذبيحة الكافر غير الكتابي","يشترط أن يكون الذابح ذكراً بالغاً فقط","تحل ذبيحة كل من ذكر اسم الله مهما كان دينه","تحل ذبيحة أهل الكتاب مطلقاً"]'::jsonb, 0, 20, 7, 'multi', 'يشترط في الذابح الإسلام أو ما في حكمه، ولا تحل ذبيحة الكافر على المشهور في الفقه الجعفري، وأما أهل الكتاب فذبيحتهم محرمة عند أكثر الفقهاء الإماميين كالمحقق الحلي وصاحب الجواهر.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_13, 'ما حكم شرب عصير العنب إذا غلى واشتد قبل أن يذهب ثلثاه في الفقه الجعفري؟', '["يحل إذا طُبخ بالنار مجدداً","يكره شربه فقط ولا يحرم","يحل شربه إذا لم يُسكر","يحرم شربه ويصير نجساً على المشهور"]'::jsonb, 3, 20, 8, 'multi', 'إذا غلى عصير العنب واشتد حرم شربه ويصير نجساً على المشهور بين فقهاء الإمامية، ويحل ويطهر إذا ذهب ثلثاه بالنار، كما نص عليه العلامة الحلي وصاحب الجواهر.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_13, 'ما الحكم في الفقه الجعفري إذا اشترى شخص سلعة بشرط الخيار لمدة ثلاثة أيام ثم مات في أثناء المدة؟', '["يبطل العقد كله بوفاة أحد المتعاقدين","ينتقل خيار الشرط إلى الورثة ويقومون مقامه","يحق للبائع فسخ العقد فوراً بموت المشتري","يسقط الخيار بموت صاحبه ولا ينتقل"]'::jsonb, 1, 20, 9, 'multi', 'المشهور في الفقه الجعفري أن خيار الشرط يورَّث وينتقل إلى الورثة، فيقوم الوارث مقام الموروث في استعمال الخيار خلال المدة المتبقية، كما حققه الشيخ الأنصاري في المكاسب.', 'فقه جعفري عملي');
END $$;



DO $$
DECLARE
  v_quiz_id_14 uuid;
BEGIN
  INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
  VALUES ('أسباب النزول وآيات الأحكام', 'إسلاميات', 'علوم القرآن', 'standard', 'ar', true)
  RETURNING id INTO v_quiz_id_14;

  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_14, 'ما المقصود بـ''أسباب النزول'' في علوم القرآن؟', '["أسماء الصحابة الذين حفظوا القرآن","الأحداث والوقائع التي نزلت الآيات بسببها أو في سياقها","المراحل الزمنية لنزول القرآن الكريم","ترتيب الآيات في المصحف الشريف"]'::jsonb, 1, 20, 0, 'multi', 'أسباب النزول هي الأحداث والوقائع التي نزلت الآيات القرآنية بمناسبتها أو ردًا عليها، وهي علم مستقل من علوم القرآن يُعين على فهم معاني الآيات وتفسيرها.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_14, 'ما الأثر الفقهي لمعرفة سبب نزول الآية عند الفقهاء الجعفريين؟', '["يجعل الآية خاصة بالشخص الذي نزلت بسببه فقط","يُلغي الحاجة إلى الأحاديث الواردة عن أهل البيت عليهم السلام","يُساعد في تحديد المراد من الآية وتقييد عمومها أو إطلاقها","يُحدد ناسخ الآية ومنسوخها دائمًا"]'::jsonb, 2, 20, 1, 'multi', 'معرفة سبب النزول تُعين الفقيه على فهم مقصد الآية، وقد يُقيّد به الإطلاق أو يُخصص به العموم، وإن كانت القاعدة المشهورة أن ''العبرة بعموم اللفظ لا بخصوص السبب''.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_14, 'ما الآية المعروفة بـ''آية الولاية'' التي يستدل بها الفقهاء الجعفريون على إمامة علي عليه السلام؟', '["آية 1 من سورة النساء: ''يا أيها الناس اتقوا ربكم...''","آية 3 من سورة المائدة: ''اليوم أكملت لكم دينكم...''","آية 67 من سورة المائدة: ''يا أيها الرسول بلّغ ما أنزل إليك...''","آية 55 من سورة المائدة: ''إنما وليكم الله ورسوله والذين آمنوا...''"]'::jsonb, 3, 20, 2, 'multi', 'آية 55 من سورة المائدة تُعرف بآية الولاية، ويرى الفقهاء الجعفريون أنها نزلت في الإمام علي عليه السلام حين تصدّق بخاتمه وهو راكع، وهو دليل على ولايته.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_14, 'ما سبب نزول آية التبليغ في سورة المائدة (الآية 67) وفق الروايات الواردة في المصادر الجعفرية؟', '["نزلت في سياق الدعوة الجهرية في مكة المكرمة","نزلت بمناسبة أمر النبي صلى الله عليه وآله بإعلان ولاية علي عليه السلام في غدير خم","نزلت لأمر النبي بتبليغ أحكام الزكاة للمسلمين","نزلت لحث النبي على تبليغ أحكام الحج الأكبر"]'::jsonb, 1, 20, 3, 'multi', 'تُجمع الروايات الجعفرية على أن آية التبليغ نزلت في غدير خم لأمر النبي صلى الله عليه وآله بالإعلان الصريح عن ولاية الإمام علي عليه السلام، وهو ما فعله النبي في حجة الوداع.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_14, 'ما القاعدة الأصولية المتعلقة بعلاقة سبب النزول بالحكم المستفاد من الآية؟', '["العبرة بعموم اللفظ لا بخصوص السبب","السبب يُلغي الحكم إذا زال موضوعه","السبب ينسخ الآية عند انتهاء الواقعة","العبرة بخصوص السبب لا بعموم اللفظ"]'::jsonb, 0, 20, 4, 'multi', 'القاعدة الأصولية المشهورة عند الفقهاء هي ''العبرة بعموم اللفظ لا بخصوص السبب''، أي أن الحكم المستفاد من الآية يشمل كل من ينطبق عليه اللفظ وليس فقط من نزلت بسببه.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_14, 'ما الآية القرآنية المعروفة بـ''آية التطهير'' ويستدل بها على عصمة أهل البيت عليهم السلام؟', '["الآية 61 من سورة آل عمران: ''فقل تعالوا ندع أبناءنا وأبناءكم...''","الآية 55 من سورة المائدة: ''إنما وليكم الله ورسوله...''","الآية 7 من سورة الحشر: ''وما آتاكم الرسول فخذوه...''","الآية 33 من سورة الأحزاب: ''إنما يريد الله ليذهب عنكم الرجس أهل البيت...''"]'::jsonb, 3, 20, 5, 'multi', 'آية التطهير هي الآية 33 من سورة الأحزاب، وتُعدّ من أبرز الأدلة على عصمة أهل البيت عليهم السلام، ويرى الجعفريون أن المقصود بـ''أهل البيت'' هم النبي وعلي وفاطمة والحسن والحسين عليهم السلام.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_14, 'ما المقصود بـ''آيات الأحكام'' في علوم الفقه الجعفري؟', '["الآيات المتعلقة بالعقيدة والتوحيد فقط","الآيات القرآنية التي تتضمن أحكامًا شرعية فقهية عبادية أو معاملاتية","الآيات التي نسخت أحكام التوراة والإنجيل","الآيات التي تتحدث عن قصص الأنبياء والأمم السابقة"]'::jsonb, 1, 20, 6, 'multi', 'آيات الأحكام هي الآيات القرآنية التي تتضمن أحكامًا شرعية تكليفية أو وضعية، وتشمل العبادات والمعاملات والأحوال الشخصية وغيرها، وقد أُفرد لها علم مستقل يُسمى ''فقه القرآن'' أو ''آيات الأحكام''.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_14, 'ما الكتاب الفقهي الجعفري الشهير المخصص لدراسة آيات الأحكام؟', '["الروضة البهية في شرح اللمعة الدمشقية","المبسوط في فقه الإمامية للشيخ الطوسي","كنز العرفان في فقه القرآن للفاضل المقداد","شرائع الإسلام للمحقق الحلي"]'::jsonb, 2, 20, 7, 'multi', 'كتاب ''كنز العرفان في فقه القرآن'' للفاضل المقداد السيوري الحلي (ت 826هـ) هو من أبرز المصنفات الجعفرية المتخصصة في استنباط الأحكام الفقهية من آيات القرآن الكريم.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_14, 'ما سبب نزول آية المباهلة (آل عمران: 61) وما دلالتها عند الجعفريين؟', '["نزلت لمباهلة نصارى نجران، وتدل على فضل علي وفاطمة والحسنين عليهم السلام","نزلت في سياق الحوار مع المشركين في مكة المكرمة","نزلت لمباهلة يهود المدينة الذين أنكروا نبوة محمد صلى الله عليه وآله","نزلت لإثبات أفضلية المسلمين على المنافقين"]'::jsonb, 0, 20, 8, 'multi', 'نزلت آية المباهلة حين جاء وفد نصارى نجران للجدال في شأن عيسى عليه السلام، فدعاهم النبي للمباهلة وأحضر عليًا وفاطمة والحسن والحسين، مما يدل على منزلتهم الرفيعة عند الله.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_14, 'ما الحكم الفقهي الذي استنبطه الفقهاء الجعفريون من آية ''وأمرهم شورى بينهم'' (الشورى: 38)؟', '["تنسخ الآيات الدالة على ولاية أهل البيت عليهم السلام","تدل على إلزامية الشورى في جميع القرارات الفردية","تدل على وجوب الشورى في تعيين الإمام والحاكم","لا تدل على مشروعية الشورى في تعيين الإمام لأن الإمامة نص إلهي لا اختيار بشري"]'::jsonb, 3, 20, 9, 'multi', 'يرى الفقهاء الجعفريون أن آية الشورى واردة في سياق صفات المؤمنين في شؤونهم الدنيوية، ولا تدل على مشروعية الشورى في تعيين الإمام، لأن الإمامة عندهم منصب إلهي يُعيّن بالنص لا بالاختيار.', 'علوم القرآن');
END $$;



DO $$
DECLARE
  v_quiz_id_15 uuid;
BEGIN
  INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
  VALUES ('المكي والمدني وتاريخ جمع القرآن', 'إسلاميات', 'علوم القرآن', 'standard', 'ar', true)
  RETURNING id INTO v_quiz_id_15;

  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_15, 'ما المعيار الراجح عند جمهور العلماء في تعريف المكي والمدني؟', '["ما نزل في الليل وما نزل في النهار","ما نزل في مكة وما نزل في المدينة","ما نزل قبل الهجرة وما نزل بعدها","ما خوطب به أهل مكة وما خوطب به أهل المدينة"]'::jsonb, 2, 20, 0, 'multi', 'الراجح عند جمهور العلماء أن المكي ما نزل قبل الهجرة النبوية ولو في غير مكة، والمدني ما نزل بعد الهجرة ولو في غير المدينة، وهذا المعيار الزمني هو الأدق والأشمل.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_15, 'أي السور الآتية تُعدّ من السور المدنية باتفاق؟', '["سورة الفاتحة","سورة البقرة","سورة الضحى","سورة الإخلاص"]'::jsonb, 1, 20, 1, 'multi', 'سورة البقرة من أوائل السور التي نزلت بعد الهجرة في المدينة المنورة، وهي مدنية باتفاق العلماء، وتتضمن أحكام الصيام والجهاد والمعاملات.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_15, 'ما السمة الغالبة على السور المكية من حيث المضمون؟', '["تنظيم شؤون الدولة والجهاد","تفصيل أحكام المواريث والحدود","تفصيل أحكام الزواج والطلاق","الدعوة إلى التوحيد وتقرير العقيدة وقصص الأنبياء"]'::jsonb, 3, 20, 2, 'multi', 'السور المكية تتسم بغلبة الدعوة إلى التوحيد وإثبات الرسالة والبعث والنشور، والرد على المشركين، وسرد قصص الأنبياء، لأن الخطاب كان موجهاً لمجتمع لم يؤمن بعد.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_15, 'من هو الصحابي الذي أشار على أبي بكر الصديق بجمع القرآن في مصحف واحد بعد موقعة اليمامة؟', '["عمر بن الخطاب","زيد بن ثابت","علي بن أبي طالب","عثمان بن عفان"]'::jsonb, 0, 20, 3, 'multi', 'عمر بن الخطاب هو من أشار على أبي بكر الصديق بجمع القرآن بعد مقتل كثير من حفظة القرآن في موقعة اليمامة، خشية ضياع القرآن بوفاة الحفاظ.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_15, 'من أشرف على لجنة جمع القرآن وكتابته في عهد أبي بكر الصديق؟', '["أبي بن كعب","زيد بن ثابت","عبد الله بن مسعود","معاذ بن جبل"]'::jsonb, 1, 20, 4, 'multi', 'زيد بن ثابت الأنصاري هو الذي أشرف على جمع القرآن وكتابته في عهد أبي بكر، وقد اختير لحداثة سنّه وحضوره عرض القرآن الأخير على النبي صلى الله عليه وآله.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_15, 'ما الذي ميّز جمع عثمان بن عفان للقرآن عن جمع أبي بكر؟', '["ترتيب الآيات داخل السور","جمع القرآن لأول مرة من الألواح والصدور","توحيد المصاحف على حرف واحد وحرق ما سواها","إضافة التشكيل والنقط للمصحف"]'::jsonb, 2, 20, 5, 'multi', 'جمع عثمان كان الهدف منه توحيد المسلمين على مصحف واحد بلهجة قريش، وإرسال نسخ إلى الأمصار وحرق ما عداها من صحف ومصاحف مختلفة، لمنع الاختلاف في قراءة القرآن.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_15, 'ما السورة التي يُختلف في كونها مكية أم مدنية وأشهر الأقوال أنها مكية لكنها تضمنت آيات مدنية؟', '["سورة الحج","سورة الأعراف","سورة الأعلى","سورة البقرة"]'::jsonb, 0, 20, 6, 'multi', 'سورة الحج من السور التي اختُلف فيها اختلافاً واسعاً، فبعضها يُعدّ مكياً وبعضها مدنياً، وقال بعض العلماء إنها نزلت في الطريق بين مكة والمدينة، وهي نموذج على السور المختلطة.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_15, 'ما الضابط الذي ذكره العلماء لمعرفة الآية المكية داخل السورة المدنية؟', '["كل آية تتحدث عن الصلاة فهي مكية","كل آية تتحدث عن الجهاد فهي مدنية","كل آية تذكر المنافقين فهي مكية","كل آية تبدأ بـ ''يا أيها الناس'' فهي مكية"]'::jsonb, 3, 20, 7, 'multi', 'من الضوابط الاستقرائية المشهورة عند العلماء أن خطاب ''يا أيها الناس'' يغلب في السور المكية لأنه خطاب عام، بينما ''يا أيها الذين آمنوا'' يغلب في السور المدنية لأنه خطاب للمؤمنين المجتمعين.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_15, 'ما عدد السور المكية تقريباً من إجمالي سور القرآن الكريم البالغة 114 سورة؟', '["نحو 100 سورة","نحو 50 سورة","نحو 82 سورة","نحو 30 سورة"]'::jsonb, 2, 20, 8, 'multi', 'يُقدّر جمهور العلماء عدد السور المكية بنحو 82 إلى 86 سورة، والمدنية بنحو 28 إلى 30 سورة، وبعضها مختلف فيه، مما يدل على أن الجزء الأكبر من القرآن نزل قبل الهجرة.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_15, 'ما الموقف الذي يذهب إليه كثير من علماء الإمامية بشأن جمع القرآن وترتيبه؟', '["أن الإمام علياً جمع القرآن مرتباً حسب النزول بعد وفاة النبي مباشرة","أن القرآن لم يُجمع في عهد النبي قط","أن ترتيب الآيات اجتهادي لا توقيفي","أن القرآن جُمع في عهد أبي بكر فقط ولا حاجة لجمع عثمان"]'::jsonb, 0, 20, 9, 'multi', 'يذهب كثير من علماء الإمامية إلى أن الإمام علياً عليه السلام جمع القرآن بعد وفاة النبي مرتباً حسب النزول وفق ما أوصى به النبي، وأنه حمله على ناقته وعرضه على الصحابة فلم يقبلوه، وأودعه لمن بعده من الأئمة.', 'علوم القرآن');
END $$;



DO $$
DECLARE
  v_quiz_id_16 uuid;
BEGIN
  INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
  VALUES ('الناسخ والمنسوخ والمحكم والمتشابه', 'إسلاميات', 'علوم القرآن', 'standard', 'ar', true)
  RETURNING id INTO v_quiz_id_16;

  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_16, 'ما التعريف الاصطلاحي للناسخ في علوم القرآن عند علماء الإمامية؟', '["هو البيان الذي يخصّص العام","هو الآية التي تُفسّر آية أخرى غامضة","هو الدليل الشرعي الذي يرفع حكماً ثابتاً بدليل شرعي سابق","هو النص الذي يُقيّد المطلق"]'::jsonb, 2, 20, 0, 'multi', 'عرّف علماء الإمامية كالشيخ الطوسي في التبيان الناسخَ بأنه الدليل الشرعي الرافع لحكم ثابت بدليل شرعي متقدم، وهو تعريف يستوجب وجود حكم سابق وارتفاعه بالنص اللاحق.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_16, 'ما شرط النسخ الذي اشترطه الشيخ الطوسي في التبيان ليكون الرفع نسخاً حقيقياً؟', '["أن يكون الحكم المنسوخ مقيداً بزمن معيّن","أن يكون الحكم المنسوخ مؤبداً في ظاهره ثم ارتفع بدليل لاحق","أن يتأخر الناسخ عن المنسوخ بسنة كاملة","أن يكون الناسخ حديثاً نبوياً لا قرآناً"]'::jsonb, 1, 20, 1, 'multi', 'اشترط الشيخ الطوسي في التبيان أن يكون الحكم المنسوخ ظاهره الدوام والاستمرار، فإن كان مؤقتاً فانقضاؤه بانتهاء وقته ليس نسخاً بل إتمام لمدته.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_16, 'ما الموقف الإمامي من نسخ القرآن بالسنة الآحادية؟', '["لا يجوز نسخ القرآن بخبر الواحد لأن القطعي لا يُرفع بالظني","يجوز إن كان الراوي معصوماً فقط","يجوز ذلك إن صحّت سند الرواية","أجازه أكثر علماء الإمامية بلا قيد"]'::jsonb, 0, 20, 2, 'multi', 'ذهب محققو الإمامية كالسيد الخوئي في البيان إلى أن نسخ القرآن القطعي الدلالة بخبر الواحد الظني غير جائز، لأن القطعي لا يُرفع بالظني.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_16, 'كم آية حدّدها السيد الخوئي في كتابه البيان على أنها منسوخة تحديداً علمياً دقيقاً؟', '["عشر آيات","مئتان وأربع عشرة آية","لم يُثبت نسخاً في القرآن أصلاً","آية واحدة وهي آية المناجاة"]'::jsonb, 3, 20, 3, 'multi', 'أثبت السيد الخوئي في البيان بعد فحص دقيق أن معظم ما ادّعي نسخه ليس نسخاً حقيقياً، وأن ما يمكن قبوله بصورة محققة ضيّق جداً، وقد اعتمد آية المناجاة في سورة المجادلة نموذجاً للنسخ الصحيح.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_16, 'ما المراد بالمحكم في القرآن الكريم وفق تعريف الشيخ الطوسي في التبيان؟', '["هو الآية التي نزلت في مكة فقط","هو كل آية لم تُنسخ","هو ما استقلّ بمعناه وأحكمت دلالته فلا يحتاج إلى بيان خارجي","هو النص الذي أجمع المفسرون على معناه"]'::jsonb, 2, 20, 4, 'multi', 'عرّف الشيخ الطوسي في التبيان المحكم بأنه ما أُحكمت دلالته وكان واضح المعنى لا يحتمل التأويل المتعدد، وهو أم الكتاب الذي يُرجع إليه عند الاشتباه.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_16, 'ما المتشابه في القرآن عند العلامة الطباطبائي في الميزان؟', '["هو الآية التي تتعلق بالغيبيات فحسب","هو الآية التي تحتمل وجوهاً متعددة ولا تستقل بمعناها إلا بردّها إلى المحكم","هو النص الذي خالف العقل","هو كل آية نُسخت"]'::jsonb, 1, 20, 5, 'multi', 'ذهب العلامة الطباطبائي في الميزان إلى أن المتشابه هو ما يتشابه على الفهم ويحتاج إلى ردّه إلى المحكم الذي هو أم الكتاب لتحديد مراده، وهو ليس مبهماً مطلقاً بل يتضح بالرجوع إلى المحكمات.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_16, 'من الذي يعلم تأويل المتشابهات في القرآن وفق آية آل عمران السابعة كما يُفسّرها علماء الإمامية؟', '["الله تعالى والراسخون في العلم وهم الأنبياء والأئمة المعصومون","العلماء المجتهدون بالاجتهاد المطلق","الله تعالى وحده دون سواه","جميع المؤمنين الصادقين"]'::jsonb, 0, 20, 6, 'multi', 'فسّر علماء الإمامية كالشيخ الطوسي والطباطبائي الراسخين في العلم بأنهم النبي والأئمة المعصومون، وأن الواو في قوله تعالى ''والراسخون في العلم'' عاطفة لا استئنافية، فيكون الأئمة شركاء في علم التأويل.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_16, 'ما نوع النسخ الذي ذهب إليه جمهور علماء الإمامية في قضية نسخ التلاوة مع بقاء الحكم؟', '["اختلفوا فيه بين مُجيز ومانع مناصفة","قبلوه في آيات الرجم فقط","قبلوه إذا صحّت الرواية","رفضوه جملةً وتفصيلاً ولم يقبلوا نسخ التلاوة مع بقاء الحكم"]'::jsonb, 3, 20, 7, 'multi', 'رفض محققو الإمامية كالسيد الخوئي نسخ التلاوة رفضاً قاطعاً مستدلّين بحفظ القرآن المذكور في الآية الكريمة ''إنا نحن نزلنا الذكر وإنا له لحافظون''، فضلاً عن التواتر الذي تثبت به القرآنية.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_16, 'ما العلاقة بين المحكم والمتشابه في منهج الاستدلال الفقهي الإمامي؟', '["يُترك المتشابه ولا يُستدل به ولا يُفسَّر","المتشابهات مقدّمة على المحكمات لخصوصيتها","المحكمات هي الأصل والمرجع، وتُحمل المتشابهات عليها وتُفسَّر في ضوئها","المحكم والمتشابه متساويان في الحجية"]'::jsonb, 2, 20, 8, 'multi', 'أقرّ الفقهاء الإماميون قاعدة أن المحكمات أمّهات الكتاب ومرجعه، وأن المتشابهات تُردّ إليها وتُفسّر في ضوئها، وهذا منهج التفسير القرآني بالقرآن الذي أكده الأئمة عليهم السلام.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_16, 'ما الفرق الجوهري بين النسخ والتخصيص عند الأصوليين الإماميين كالمحقق الحلي؟', '["التخصيص خاص بالسنة والنسخ خاص بالقرآن","النسخ رفع لحكم ثابت بعد العمل به، والتخصيص بيان لإخراج بعض الأفراد من عموم الحكم ابتداءً","النسخ أعم من التخصيص مطلقاً","النسخ والتخصيص مترادفان في الاصطلاح الأصولي"]'::jsonb, 1, 20, 9, 'multi', 'فرّق الأصوليون الإماميون كالمحقق الحلي في المعارج بين النسخ والتخصيص، فالنسخ رفع للحكم بعد استقراره والعمل به، أما التخصيص فهو كشف منذ البداية عن أن العام لم يُرَد به جميع الأفراد.', 'علوم القرآن');
END $$;



DO $$
DECLARE
  v_quiz_id_17 uuid;
BEGIN
  INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
  VALUES ('إعجاز القرآن والبلاغة والقصص القرآني', 'إسلاميات', 'علوم القرآن', 'standard', 'ar', true)
  RETURNING id INTO v_quiz_id_17;

  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_17, 'ما المقصود بمصطلح ''الإعجاز البياني'' في القرآن الكريم؟', '["أن القرآن يحتوي على معلومات علمية مستقبلية فقط","عجز العرب وغيرهم عن الإتيان بمثله في بلاغته وفصاحته وأسلوبه","أن القرآن أُنزل بلغة لا يفهمها البشر","أن القرآن نُسخت تلاوته في بعض آياته"]'::jsonb, 1, 20, 0, 'multi', 'الإعجاز البياني يعني عجز الفصحاء والبلغاء عن الإتيان بمثل القرآن في نظمه وبيانه وأسلوبه، وهو أبرز وجوه إعجاز القرآن عند علماء الإمامية وغيرهم.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_17, 'ما التحدي الذي طرحه القرآن الكريم في سورة البقرة (الآية 23) للمشككين في نبوة النبي محمد صلى الله عليه وآله؟', '["الإتيان بعشر سور من مثله","الإتيان بآية واحدة مثله","الإتيان بكتاب كامل مثله","الإتيان بسورة واحدة من مثله"]'::jsonb, 3, 20, 1, 'multi', 'قال تعالى في سورة البقرة: ''فأتوا بسورة من مثله وادعوا شهداءكم من دون الله إن كنتم صادقين''، وهو تحدٍّ صريح بالإتيان بسورة واحدة.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_17, 'ما الوجه البلاغي الذي يُقصد به تعبير القرآن عن الأمر بصيغة الماضي للدلالة على تحقق الوقوع؟', '["التغليب","المجاز المرسل","صيغة الماضي للاستقبال أو التحقق","الالتفات"]'::jsonb, 2, 20, 2, 'multi', 'من أساليب القرآن البلاغية التعبير بصيغة الفعل الماضي عن الأمر المستقبلي للدلالة على تحقق وقوعه حتماً، وهو أسلوب راسخ في بلاغة العرب وقد بلغ ذروته في القرآن.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_17, 'أيٌّ من الأئمة الاثني عشر نُسب إليه تفسير بياني وعقدي مشهور للقرآن يُعرف بـ''تفسير الإمام العسكري''؟', '["الإمام علي بن أبي طالب عليه السلام","الإمام الحسن العسكري عليه السلام","الإمام محمد الباقر عليه السلام","الإمام جعفر الصادق عليه السلام"]'::jsonb, 1, 20, 3, 'multi', 'التفسير المنسوب إلى الإمام الحسن العسكري عليه السلام يتضمن بياناً لوجوه إعجاز القرآن وقصصه، وهو من المصادر التي يستشهد بها الباحثون في علوم القرآن الإمامية.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_17, 'ما القصة القرآنية التي خُصصت لها سورة كاملة تحمل اسم صاحبها وقد وصفها القرآن بأنها ''أحسن القصص''؟', '["قصة يوسف عليه السلام","قصة موسى عليه السلام","قصة إبراهيم عليه السلام","قصة عيسى عليه السلام"]'::jsonb, 0, 20, 4, 'multi', 'قال تعالى في مطلع سورة يوسف: ''نحن نقص عليك أحسن القصص''، وقد أجمع المفسرون على أن هذا الوصف يعود على قصة يوسف عليه السلام المذكورة في السورة.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_17, 'ما الظاهرة البلاغية التي يُعبّر فيها القرآن بضمير المتكلم المفرد تارةً وبضمير الجمع تارةً أخرى في سياق واحد وهي من علامات الأسلوب القرآني الرفيع؟', '["التضمين","الجناس","الالتفات","الاستعارة التصريحية"]'::jsonb, 2, 20, 5, 'multi', 'الالتفات هو الانتقال من ضمير إلى آخر أو من صيغة إلى أخرى في السياق الواحد، وهو أسلوب بلاغي رفيع أكثر منه القرآن الكريم ويُعدّ من وجوه إعجازه البياني.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_17, 'ما الذي يُميّز أسلوب القصص القرآني عن سائر القصص الأدبية وفق ما أكده العلماء المسلمون؟', '["اعتماده على الأسماء والتواريخ الدقيقة دائماً","توجيهه نحو الهداية والعبرة لا مجرد الترفيه وسرد الأحداث","اختصاره الشديد لدرجة إهمال التفاصيل كلها","اعتماده على الخيال والأسطورة لجذب القارئ"]'::jsonb, 1, 20, 6, 'multi', 'القصص القرآني يهدف أساساً إلى الهداية والعبرة والموعظة كما قال تعالى: ''لقد كان في قصصهم عبرة لأولي الألباب''، وليس غرضه الترفيه البحت أو السرد التاريخي المجرد.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_17, 'ما وجه الإعجاز في إخبار القرآن عن الغيب كقصة أصحاب الكهف وقصة ذي القرنين وغيرها؟', '["أن القرآن أخبر بأمور غيبية لم يكن في مقدور أحد معرفتها إلا بوحي إلهي","أن النبي صلى الله عليه وآله كان قد درس التوراة والإنجيل قبل النبوة","أن هذه القصص مأخوذة من الثقافة العربية الجاهلية","أن الصحابة رووها عن أهل الكتاب وأدرجوها في القرآن"]'::jsonb, 0, 20, 7, 'multi', 'إخبار القرآن عن أحداث غيبية سابقة ولاحقة يُعد من وجوه إعجازه، إذ كان النبي صلى الله عليه وآله أمياً ولم يتلق علماً من بشر، فكان ذلك دليلاً على الوحي الإلهي.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_17, 'ما المصطلح الذي يُطلق على علم دراسة أوجه إعجاز القرآن وبلاغته في التراث الإسلامي؟', '["علم الأصول","علم الكلام","علم الحديث","علم إعجاز القرآن أو علم البيان القرآني"]'::jsonb, 3, 20, 8, 'multi', 'علم إعجاز القرآن أو ما يُسمى أحياناً علم البيان القرآني يختص بدراسة الأوجه التي عجز فيها البشر عن مجاراة القرآن، وهو فرع من فروع علوم القرآن.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_17, 'ما الموقف الذي يُعبّر عنه مصطلح ''الصرفة'' في سياق الإعجاز القرآني؟', '["القول بأن العرب عارضوا القرآن فعلاً ولكنهم أخفوا ذلك","القول بأن القرآن أُنزل بلغة مصطنعة غير عربية","القول بأن الله صرف العرب عن التحدي بسلب قدرتهم على المعارضة لا لأن القرآن في ذاته معجز","القول بأن الإعجاز يقتصر على الإخبار بالغيب فقط"]'::jsonb, 2, 20, 9, 'multi', 'القائلون بالصرفة كالنظّام وبعض المعتزلة يرون أن الله صرف العرب عن معارضة القرآن بسلب قدرتهم، لا أن القرآن في ذاته فاق قدرتهم، وقد رد عليهم جمهور العلماء بأن الإعجاز في ذات القرآن وبيانه.', 'علوم القرآن');
END $$;

